const USERS_KEY = 'impacto-bi.users';
const VERSION_KEY = 'impacto-bi.users.accessVersion';
const HISTORY_KEY = 'impacto-bi.userHistory';

const state = {
  map: new Map(),
  failKeys: new Set(),
  writes: []
};

globalThis.window = {
  localStorage: {
    getItem: (key) => state.map.has(key) ? state.map.get(key) : null,
    setItem: (key, value) => {
      state.writes.push(key);
      if (state.failKeys.has(key)) throw new Error('QuotaExceededError');
      state.map.set(key, String(value));
    },
    removeItem: (key) => {
      state.map.delete(key);
    }
  }
};

let failures = 0;
let checks = 0;

function check(name, condition, detail) {
  checks += 1;
  if (condition) return;
  failures += 1;
  console.log(`FALHA: ${name}`, detail === undefined ? '' : JSON.stringify(detail));
}

async function main() {
  const { defaultDepartmentPageKeys } = await Promise.resolve().then(() => jitiImport('./src/lib/userAccessRules').then((m) => _interopRequireWildcard(m)));
  const mock = await Promise.resolve().then(() => jitiImport('./src/data/mockAdminData').then((m) => _interopRequireWildcard(m)));
  const repo = await Promise.resolve().then(() => jitiImport('./src/services/users/userRepository').then((m) => _interopRequireWildcard(m)));
  const historyRepo = await Promise.resolve().then(() => jitiImport('./src/services/users/userHistoryRepository').then((m) => _interopRequireWildcard(m)));
  const historyStorage = await Promise.resolve().then(() => jitiImport('./src/services/users/userHistoryStorage').then((m) => _interopRequireWildcard(m)));

  const admin = { id: 'usr-001', name: 'Mário Luiz Ramos' };
  const otherAdmin = { id: 'usr-002', name: 'Vagner Santos' };
  const storedHistory = () => JSON.parse(state.map.get(HISTORY_KEY) ?? '[]');
  const basic = (id) => {
    const user = repo.findUserById(id);
    return { name: user?.name ?? '', email: user?.email ?? '' };
  };
  const accessConfigOf = (id) => {
    const user = repo.findUserById(id);
    return {
      profile: 'Usuário Departamental',
      departments: (user?.departmentPageAccess ?? []).map((access) => ({
        departmentId: access.departmentId,
        pageKeys: access.pageKeys
      }))
    };
  };

  /** Base já na versão atual, sem Histórico: nenhum evento retroativo. */
  function seedStorage() {
    state.map.clear();
    state.failKeys.clear();
    state.writes = [];
    state.map.set(USERS_KEY, JSON.stringify(mock.users));
    state.map.set(VERSION_KEY, '2');
    repo.listUsers();
    state.writes = [];
  }

  // ---------- 1 e 20. Chave ausente e ausência de histórico retroativo ----------
  seedStorage();
  const emptyList = historyRepo.listUserHistoryEvents();
  check('chave ausente devolve colecao vazia', emptyList.ok === true && emptyList.events.length === 0);
  check('leitura direta devolve vazio', JSON.stringify(historyStorage.readStoredUserHistory()) === '[]');
  check('carga inicial nao cria evento', !state.map.has(HISTORY_KEY));

  // Migração completa a partir da versão 0 também não pode criar evento.
  state.map.clear();
  state.map.set(USERS_KEY, JSON.stringify(mock.users.map((user) => ({ ...user, profile: user.id === 'usr-009' ? 'Gestor' : user.profile }))));
  state.writes = [];
  repo.listUsers();
  check('migracao nao cria evento retroativo', !state.map.has(HISTORY_KEY));
  check('migracao gravou usuarios', state.writes.includes(USERS_KEY));

  // ---------- 2. JSON corrompido ----------
  seedStorage();
  state.map.set(HISTORY_KEY, '{ isto nao e json valido');
  const corrupted = historyRepo.listUserHistoryEvents();
  check('json corrompido indica falha', !corrupted.ok && corrupted.reason === 'storage-failure');
  check('json corrompido nao e apagado', state.map.get(HISTORY_KEY) === '{ isto nao e json valido');
  check('leitura direta devolve null', historyStorage.readStoredUserHistory() === null);
  const refusedByCorruption = repo.updateUserDetails(
    'usr-011',
    { name: 'Nome Novo', email: 'novo@impactotelecom.com', access: accessConfigOf('usr-011') },
    admin
  );
  check(
    'gravacao com historico ilegivel e recusada',
    !refusedByCorruption.ok && refusedByCorruption.reason === 'storage-failure'
  );
  check('historico corrompido continua intacto', state.map.get(HISTORY_KEY) === '{ isto nao e json valido');
  check('usuario nao foi alterado', repo.findUserById('usr-011')?.name === 'Emerson Ribeiro dos Santos');

  // ---------- 3 e 4. Edição gera um único evento com os campos alterados ----------
  seedStorage();
  const beforeEdit = repo.findUserById('usr-011');
  const edited = repo.updateUserDetails(
    'usr-011',
    {
      name: 'Emerson Ribeiro',
      email: 'emerson.ribeiro@impactotelecom.com',
      access: { profile: 'Executivo' }
    },
    admin
  );
  check('edicao concluida', edited.ok === true && edited.changed === true);
  const editEvents = storedHistory();
  check('edicao gera exatamente um evento', editEvents.length === 1);
  const editEvent = editEvents[0];
  check('acao updated', editEvent?.action === 'updated');
  check('alvo e responsavel registrados',
  editEvent?.targetUserId === 'usr-011' &&
  editEvent?.targetUserName === 'Emerson Ribeiro' &&
  editEvent?.actorUserId === 'usr-001' &&
  editEvent?.actorName === 'Mário Luiz Ramos'
  );
  check(
    'occurredAt igual ao audit.updatedAt',
    edited.ok === true && editEvent?.occurredAt === edited.user.audit?.updatedAt
  );
  check('detalhe de nome', editEvent?.details[0] === 'Nome: Emerson Ribeiro dos Santos → Emerson Ribeiro');
  check(
    'detalhe de email',
    editEvent?.details[1] === `E-mail: ${beforeEdit?.email} → emerson.ribeiro@impactotelecom.com`
  );
  check('detalhe de perfil', editEvent?.details[2] === 'Perfil: Usuário Departamental → Executivo');
  check(
    'nenhum detalhe de campo inalterado',
    !editEvent?.details.some((detail) => detail.startsWith('Status'))
  );
  check('gravou usuarios e historico juntos',
  state.writes.filter((key) => key === USERS_KEY).length === 1 &&
  state.writes.filter((key) => key === HISTORY_KEY).length === 1
  );

  // ---------- 5 e 6. Departamento inteiro adicionado e removido ----------
  seedStorage();
  repo.updateUserDetails(
    'usr-011',
    {
      ...basic('usr-011'),
      access: {
        profile: 'Usuário Departamental',
        departments: [
        { departmentId: 'comercial', pageKeys: defaultDepartmentPageKeys('comercial') },
        { departmentId: 'cop', pageKeys: defaultDepartmentPageKeys('cop') }]

      }
    },
    admin
  );
  const addedEvent = storedHistory()[0];
  check('departamento adicionado registrado', addedEvent?.details.includes('Departamento adicionado: COP'));
  check(
    'departamento adicionado nao lista paginas',
    !addedEvent?.details.some((detail) => detail.startsWith('Página adicionada em COP'))
  );
  check('detalhes enxutos na adicao', addedEvent?.details.length === 1, addedEvent?.details);

  repo.updateUserDetails(
    'usr-011',
    {
      ...basic('usr-011'),
      access: {
        profile: 'Usuário Departamental',
        departments: [{ departmentId: 'comercial', pageKeys: defaultDepartmentPageKeys('comercial') }]
      }
    },
    admin
  );
  const removedEvent = storedHistory()[1];
  check('departamento removido registrado', removedEvent?.details.includes('Departamento removido: COP'));
  check(
    'departamento removido nao lista paginas',
    !removedEvent?.details.some((detail) => detail.startsWith('Página removida em COP'))
  );

  // ---------- 7. Modelo liberado e removido ----------
  const withModel = defaultDepartmentPageKeys('comercial').concat('model');
  repo.updateUserDetails(
    'usr-011',
    {
      ...basic('usr-011'),
      access: {
        profile: 'Usuário Departamental',
        departments: [{ departmentId: 'comercial', pageKeys: withModel }]
      }
    },
    admin
  );
  const modelGranted = storedHistory()[2];
  check('modelo liberado com texto proprio', modelGranted?.details.includes('Modelo liberado: Comercial'));
  check(
    'modelo nao usa mensagem generica',
    !modelGranted?.details.some((detail) => detail.includes('Página adicionada em Comercial: Modelo'))
  );

  const withoutCalendar = defaultDepartmentPageKeys('comercial').filter((key) => key !== 'reports');
  repo.updateUserDetails(
    'usr-011',
    {
      ...basic('usr-011'),
      access: {
        profile: 'Usuário Departamental',
        departments: [{ departmentId: 'comercial', pageKeys: withoutCalendar }]
      }
    },
    admin
  );
  const modelRemoved = storedHistory()[3];
  check('modelo removido com texto proprio', modelRemoved?.details.includes('Modelo removido: Comercial'));
  check(
    'pagina comum removida usa rotulo oficial',
    modelRemoved?.details.includes('Página removida em Comercial: Relatórios')
  );

  // ---------- 18 e 19. Eventos consecutivos e ordenação ----------
  check('eventos consecutivos preservados', storedHistory().length === 4);
  const listed = historyRepo.listUserHistoryEvents();
  check('listagem ok', listed.ok === true && listed.events.length === 4);
  if (listed.ok) {
    const occurred = listed.events.map((event) => event.occurredAt);
    check(
      'mais recente primeiro',
      occurred.every((value, index) => index === 0 || occurred[index - 1] >= value)
    );
    check(
      'ultimo evento gravado vem primeiro',
      listed.events[0].details.includes('Modelo removido: Comercial')
    );
    listed.events[0].details.push('mutação externa');
    check(
      'listagem devolve copias',
      historyRepo.listUserHistoryEvents().ok === true &&
      !storedHistory()[3].details.includes('mutação externa')
    );
  }

  // ---------- 8 e 9. Idempotência e recusa não geram evento ----------
  seedStorage();
  const idempotent = repo.updateUserDetails(
    'usr-011',
    { ...basic('usr-011'), access: accessConfigOf('usr-011') },
    admin
  );
  check('edicao idempotente', idempotent.ok === true && idempotent.changed === false);
  check('idempotente nao cria evento', !state.map.has(HISTORY_KEY));
  check('idempotente nao grava', state.writes.length === 0);

  const refused = repo.updateUserDetails(
    'usr-001',
    { ...basic('usr-001'), access: { profile: 'Executivo' } },
    admin
  );
  check('autoedicao recusada', !refused.ok && refused.reason === 'self-access-change');
  check('recusa nao cria evento', !state.map.has(HISTORY_KEY));

  const emailTaken = repo.updateUserDetails(
    'usr-011',
    { name: 'Qualquer', email: 'marioramos@impactotelecom.com', access: { profile: 'Executivo' } },
    admin
  );
  check('email duplicado recusado', !emailTaken.ok && emailTaken.reason === 'email-taken');
  check('recusa por email nao cria evento', !state.map.has(HISTORY_KEY));

  // ---------- 10, 11, 12 e 13. Status ----------
  seedStorage();
  const deactivated = repo.deactivateUser('usr-011', admin);
  check('desativacao ok', deactivated.ok === true && deactivated.changed === true);
  const statusEvents = storedHistory();
  check('desativacao gera um evento', statusEvents.length === 1);
  check('acao deactivated', statusEvents[0]?.action === 'deactivated');
  check('detalhe de status', JSON.stringify(statusEvents[0]?.details) === JSON.stringify(['Status: Ativo → Inativo']));
  check(
    'occurredAt igual ao audit.deactivatedAt',
    deactivated.ok === true && statusEvents[0]?.occurredAt === deactivated.user.audit?.deactivatedAt
  );

  const alreadyInactive = repo.deactivateUser('usr-011', admin);
  check('desativacao idempotente', alreadyInactive.ok === true && alreadyInactive.changed === false);
  check('desativacao idempotente nao cria evento', storedHistory().length === 1);

  const selfDeactivation = repo.deactivateUser('usr-001', admin);
  check('auto desativacao recusada', !selfDeactivation.ok && selfDeactivation.reason === 'self-deactivation');
  check('recusa de status nao cria evento', storedHistory().length === 1);

  repo.deactivateUser('usr-002', admin);
  repo.deactivateUser('usr-003', admin);
  const lastAdmin = repo.deactivateUser('usr-001', otherAdmin);
  check('ultimo administrador protegido', !lastAdmin.ok && lastAdmin.reason === 'last-active-administrator');
  check('protecao nao cria evento', storedHistory().length === 3);

  const reactivated = repo.activateUser('usr-011', admin);
  check('reativacao ok', reactivated.ok === true && reactivated.changed === true);
  const reactivationEvent = storedHistory().at(-1);
  check('acao reactivated', reactivationEvent?.action === 'reactivated');
  check(
    'detalhe da reativacao',
    JSON.stringify(reactivationEvent?.details) === JSON.stringify(['Status: Inativo → Ativo'])
  );
  const alreadyActive = repo.activateUser('usr-011', admin);
  check('reativacao idempotente nao cria evento', alreadyActive.ok === true && storedHistory().length === 4);

  // ---------- 14, 15, 16 e 17. Falhas de gravação ----------
  for (const failing of [HISTORY_KEY, USERS_KEY, VERSION_KEY]) {
    seedStorage();
    repo.deactivateUser('usr-016', admin);
    const usersBefore = state.map.get(USERS_KEY);
    const versionBefore = state.map.get(VERSION_KEY);
    const historyBefore = state.map.get(HISTORY_KEY);

    state.failKeys.add(failing);
    const failed = repo.updateUserDetails(
      'usr-011',
      { name: 'Nome Que Nao Grava', email: 'naograva@impactotelecom.com', access: { profile: 'Executivo' } },
      admin
    );
    state.failKeys.clear();

    check(`falha em ${failing} devolve storage-failure`, !failed.ok && failed.reason === 'storage-failure');
    check(`falha em ${failing} preserva usuarios`, state.map.get(USERS_KEY) === usersBefore);
    check(`falha em ${failing} preserva versao`, state.map.get(VERSION_KEY) === versionBefore);
    check(`falha em ${failing} preserva historico`, state.map.get(HISTORY_KEY) === historyBefore);
    check(
      `falha em ${failing} nao muda a memoria`,
      repo.findUserById('usr-011')?.name === 'Emerson Ribeiro dos Santos' &&
      repo.findUserById('usr-011')?.profile === 'Usuário Departamental'
    );
    check(`falha em ${failing} nao cria evento`, storedHistory().length === 1);
  }

  // Falha na primeira gravação de Histórico remove a chave que não existia.
  seedStorage();
  state.failKeys.add(HISTORY_KEY);
  const firstEventFailure = repo.deactivateUser('usr-016', admin);
  state.failKeys.clear();
  check('primeira falha devolve storage-failure', !firstEventFailure.ok);
  check('chave de historico inexistente nao e criada', !state.map.has(HISTORY_KEY));
  check('status nao mudou', repo.findUserById('usr-016')?.status === 'Ativo');

  console.log(`\n${checks - failures}/${checks} verificacoes passaram`);
  if (failures) process.exitCode = 1;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
}); /* v9-bd70852d4d2e2d3e */
